from aide import L, st, e, v, d, ch, li, od

UNIT = ("Récits et regrets", "🎞️", "Raconter avec précision et exprimer des regrets.", [

L("🎬", "Les temps narratifs avancés",
  "Ajouter le past perfect continu à tes récits.",
  [st("🎬", "Past perfect continuous : had been + -ing. Il insiste sur la DURÉE d’une action avant un moment passé : She had been waiting for an hour when the bus finally came."),
   st("🔎", "Il explique souvent une situation passée : The ground was wet. It had been raining all night."),
   st("⚖️", "Comparer : I had read the book (terminé) / I had been reading for hours (activité, durée)."),
   st("🧩", "Les quatre temps du récit ensemble : passé simple, passé continu, past perfect, past perfect continuous.")],
  [e("🚌", "She had been waiting for an hour when the bus finally arrived.", "Elle attendait depuis une heure quand l’autobus est enfin arrivé."),
   e("💦", "The streets were wet because it had been raining all night.", "Les rues étaient mouillées parce qu’il avait plu toute la nuit."),
   e("😴", "I was exhausted. I had been working since dawn.", "J’étais épuisé. Je travaillais depuis l’aube."),
   e("🏃", "They were out of breath because they had been running.", "Ils étaient essoufflés parce qu’ils avaient couru."),
   e("📖", "He had been living in Paris for years before he moved back.", "Il vivait à Paris depuis des années avant de revenir.")],
  [v("🎬", "had been + -ing", "faisait depuis (avant un moment passé)", "I had been driving for hours."),
   v("😩", "exhausted", "épuisé", "I was completely exhausted."),
   v("🌅", "since dawn", "depuis l’aube", "We’d been hiking since dawn."),
   v("⏳", "finally", "enfin", "The plane finally landed."),
   v("🔙", "move back", "revenir s’installer", "She moved back to Quebec.")],
  [d("Ana", "Why were you so angry at the restaurant?", "Pourquoi étais-tu si fâché au restaurant?"),
   d("Tom", "We had been waiting for our food for forty minutes!", "On attendait notre repas depuis quarante minutes!"),
   d("Ana", "That’s ridiculous. Had they forgotten your order?", "C’est ridicule. Avaient-ils oublié votre commande?"),
   d("Tom", "Yes! And the server had been ignoring us all night.", "Oui! Et le serveur nous ignorait depuis le début de la soirée.")],
  "Le français utilise souvent l’imparfait + « depuis » là où l’anglais met le past perfect continuous : « J’attendais depuis une heure » = I had been waiting for an hour.",
  [ch("She was tired because she ___ all day.", ["had been working", "has been working", "was worked"], 0, "Durée avant un moment passé : had been working."),
   ch("When I arrived, they ___ for two hours.", ["had been waiting", "were waited", "have waited"], 0, "had been waiting for + durée."),
   ch("I ___ the book, so I knew the ending. (terminé)", ["had been reading", "had read", "was reading"], 1, "Action terminée : past perfect simple."),
   ch("The grass was wet. It ___ .", ["had been raining", "has rained", "rains"], 0, "Explication d’une situation passée."),
   li("We had been driving for hours.", ["We had been driving for hours.", "We have been driving for hours.", "We had driven for hours."], 0, "had been driving."),
   od("She had been waiting for an hour", "Elle attendait depuis une heure", "had been + -ing + for.")]),

L("🔙", "Le troisième conditionnel",
  "Imaginer un passé différent.",
  [st("🔙", "Formation : If + past perfect, would have + participe passé. If I had known, I would have come."),
   st("🌫️", "Il parle d’une situation IRRÉELLE dans le passé : ce qui ne s’est pas passé et ses conséquences imaginaires."),
   st("🗣️", "À l’oral : If I’d known, I’d have come (« I’d’ve »). Attention : le premier ’d = had, le deuxième = would."),
   st("🔀", "could have / might have : If we had left earlier, we could have caught the train.")],
  [e("📞", "If I had known, I would have called you.", "Si j’avais su, je t’aurais appelé."),
   e("🚆", "If we had left earlier, we wouldn’t have missed the train.", "Si nous étions partis plus tôt, nous n’aurions pas manqué le train."),
   e("🎓", "She would have passed if she had studied more.", "Elle aurait réussi si elle avait étudié davantage."),
   e("☂️", "If it hadn’t rained, we could have gone to the beach.", "S’il n’avait pas plu, nous aurions pu aller à la plage."),
   e("💔", "If he hadn’t moved to Toronto, they might have stayed together.", "S’il n’avait pas déménagé à Toronto, ils seraient peut-être restés ensemble.")],
  [v("🔙", "would have + participe", "aurait (fait)", "I would have helped."),
   v("💪", "could have", "aurait pu", "We could have won."),
   v("🎲", "might have", "aurait peut-être", "It might have worked."),
   v("🚆", "miss", "manquer, rater", "We missed the bus."),
   v("😮", "If only I had known!", "Si seulement j’avais su!", "If only I had known earlier!")],
  [d("Lou", "Why didn’t you come to the party?", "Pourquoi n’es-tu pas venu à la fête?"),
   d("Max", "Nobody told me! If I had known, I would have come.", "Personne ne me l’a dit! Si j’avais su, je serais venu."),
   d("Lou", "I sent you a message!", "Je t’ai envoyé un message!"),
   d("Max", "Really? If I had checked my phone, I would have seen it…", "Vraiment? Si j’avais regardé mon téléphone, je l’aurais vu…")],
  "Pas de « would » après « if » : « If I would have known » est une faute très répandue, même chez les anglophones. La bonne forme : If I had known.",
  [ch("If I ___ the truth, I would have told you.", ["knew", "had known", "would have known"], 1, "If + past perfect."),
   ch("If you had asked, I ___ you.", ["would help", "would have helped", "had helped"], 1, "would have + participe."),
   ch("We ___ the game if we had played better.", ["could have won", "can win", "could win"], 0, "could have won = aurions pu gagner."),
   ch("If she ___ late, she wouldn’t have missed the flight.", ["hadn’t been", "wasn’t", "wouldn’t be"], 0, "If + past perfect (négatif)."),
   li("If I had known, I would have called you.", ["If I had known, I would have called you.", "If I knew, I would call you.", "If I had known, I will call you."], 0, "Troisième conditionnel."),
   od("If I had known I would have come", "Si j’avais su, je serais venu", "If + had + participe, would have + participe.")]),

L("🔀", "Les conditionnels mixtes",
  "Combiner une condition passée et un résultat présent (et l’inverse).",
  [st("🔀", "Passé → présent : If + past perfect, would + verbe. If I had studied medicine, I would be a doctor now."),
   st("🔁", "Présent → passé : If + passé simple, would have + participe. If I were more organized, I wouldn’t have forgotten the meeting."),
   st("🧭", "Le truc : regarde le moment de chaque moitié de la phrase et choisis le temps qui convient."),
   st("💬", "Très courant à l’oral pour les regrets : If I hadn’t moved, I wouldn’t know you!")],
  [e("🩺", "If I had studied medicine, I would be a doctor now.", "Si j’avais étudié la médecine, je serais médecin aujourd’hui."),
   e("🏠", "If we had bought that house, we would live by the lake.", "Si nous avions acheté cette maison, nous habiterions au bord du lac."),
   e("🗓️", "If she were more organized, she wouldn’t have missed the deadline.", "Si elle était plus organisée, elle n’aurait pas manqué l’échéance."),
   e("🤝", "If I hadn’t moved to Montreal, I wouldn’t know you.", "Si je n’avais pas déménagé à Montréal, je ne te connaîtrais pas."),
   e("💬", "If he spoke English, he would have understood the joke.", "S’il parlait anglais, il aurait compris la blague.")],
  [v("🔀", "mixed conditional", "conditionnel mixte", "That’s a mixed conditional."),
   v("🩺", "would be", "serait", "I would be rich now."),
   v("🗓️", "deadline", "échéance", "We missed the deadline."),
   v("🤷", "otherwise", "sinon", "I left early, otherwise I’d have been late."),
   v("🌱", "turn out", "s’avérer", "It turned out well.")],
  [d("Jen", "Do you ever regret not becoming a lawyer?", "Regrettes-tu parfois de ne pas être devenu avocat?"),
   d("Raf", "Sometimes. If I had finished law school, I would earn more now.", "Parfois. Si j’avais fini mon droit, je gagnerais plus aujourd’hui."),
   d("Jen", "But would you be happy?", "Mais serais-tu heureux?"),
   d("Raf", "Probably not. If I were a lawyer, I would have quit by now!", "Probablement pas. Si j’étais avocat, j’aurais démissionné depuis longtemps!")],
  "Mot indice : « now » dans le résultat → would + verbe. « then / yesterday » dans le résultat → would have + participe.",
  [ch("If I had saved money, I ___ rich now.", ["would be", "would have been", "will be"], 0, "Résultat présent (now) : would be."),
   ch("If she ___ shy, she would have spoken at the meeting.", ["weren’t", "won’t be", "wouldn’t be"], 0, "Caractère permanent (présent) : weren’t."),
   ch("If they had taken the job, they ___ in Vancouver now.", ["would live", "would have lived", "lived"], 0, "Résultat présent : would live."),
   ch("If I spoke Spanish, I ___ the job in Mexico last year.", ["would get", "would have gotten", "got"], 1, "Résultat passé : would have gotten."),
   li("If I had studied medicine, I would be a doctor now.", ["If I had studied medicine, I would be a doctor now.", "If I studied medicine, I would be a doctor now.", "If I had studied medicine, I would have been a doctor now."], 0, "Passé → présent."),
   od("If I had moved I would not know you", "Si j’avais déménagé, je ne te connaîtrais pas", "Conditionnel mixte.")]),

L("😔", "Regrets : wish et should have",
  "Exprimer des regrets sur le passé et faire des reproches.",
  [st("😔", "wish / if only + past perfect = regret sur le passé : I wish I had studied harder. If only I hadn’t said that!"),
   st("🫵", "should have + participe = ce qu’il aurait fallu faire : You should have told me. I shouldn’t have eaten so much."),
   st("📋", "ought to have : même sens, plus formel. We ought to have booked earlier."),
   st("⚖️", "Comparer : I wish I spoke Spanish (présent) / I wish I had learned Spanish (passé).")],
  [e("📚", "I wish I had studied harder in high school.", "J’aurais aimé étudier plus fort au secondaire."),
   e("🤐", "If only I hadn’t said that!", "Si seulement je n’avais pas dit ça!"),
   e("📞", "You should have called me!", "Tu aurais dû m’appeler!"),
   e("🍰", "I shouldn’t have eaten that third piece of cake.", "Je n’aurais pas dû manger ce troisième morceau de gâteau."),
   e("🎟️", "We should have booked the tickets earlier.", "Nous aurions dû réserver les billets plus tôt.")],
  [v("😔", "I wish I had…", "J’aurais aimé…", "I wish I had known."),
   v("🫵", "should have", "aurait dû", "You should have asked."),
   v("🚫", "shouldn’t have", "n’aurait pas dû", "I shouldn’t have gone."),
   v("💭", "regret", "regretter", "I regret leaving."),
   v("🙏", "If only…", "Si seulement…", "If only I had listened!")],
  [d("Kim", "The concert is sold out!", "Le spectacle est complet!"),
   d("Paul", "Oh no. We should have bought tickets last week.", "Oh non. On aurait dû acheter les billets la semaine passée."),
   d("Kim", "I wish I had listened to you.", "J’aurais dû t’écouter."),
   d("Paul", "Well, there’s nothing we can do now.", "Bon, on n’y peut plus rien maintenant.")],
  "« J’aurais dû » = « I should have » + participe passé. Attention à l’oral : « should have » se prononce « should’ve », jamais « should of ».",
  [ch("I wish I ___ to the party. It was great!", ["went", "had gone", "would go"], 1, "Regret passé : wish + past perfect."),
   ch("You ___ me! I would have helped.", ["should tell", "should have told", "should told"], 1, "should have + participe."),
   ch("I ___ eaten so much. I feel sick.", ["shouldn’t have", "wouldn’t have", "mustn’t"], 0, "Regret : shouldn’t have."),
   ch("If only I ___ that email!", ["didn’t send", "hadn’t sent", "don’t send"], 1, "If only + past perfect."),
   li("You should have called me.", ["You should have called me.", "You should call me.", "You shouldn’t have called me."], 0, "should have = aurais dû."),
   od("I wish I had studied harder", "J’aurais aimé étudier plus fort", "wish + had + participe.")]),

L("🗨️", "Raconter avec style",
  "Rendre un récit vivant avec des verbes précis et du discours direct.",
  [st("🗨️", "Remplace les verbes simples par des verbes précis : walk → stroll (flâner), rush (se précipiter), tiptoe (marcher sur la pointe des pieds)."),
   st("🗣️", "say → whisper (chuchoter), shout (crier), mumble (marmonner), sigh (soupirer)."),
   st("💬", "Utilise le discours direct pour faire vivre une scène : “Don’t move,” she whispered."),
   st("⏳", "Crée du suspense : All of a sudden, … / Little did I know that… / It was then that…")],
  [e("🚶", "We strolled along the river after dinner.", "Nous avons flâné le long de la rivière après le souper."),
   e("🏃", "He rushed into the room, out of breath.", "Il s’est précipité dans la pièce, essoufflé."),
   e("🤫", "“Don’t move,” she whispered.", "« Ne bouge pas », a-t-elle chuchoté."),
   e("😮‍💨", "He sighed and closed the door.", "Il a soupiré et a fermé la porte."),
   e("🔮", "Little did I know that my life was about to change.", "J’étais loin de me douter que ma vie allait changer.")],
  [v("🚶", "stroll", "flâner", "Let’s stroll downtown."),
   v("🏃", "rush", "se précipiter", "She rushed out."),
   v("🤫", "whisper", "chuchoter", "Why are you whispering?"),
   v("📢", "shout", "crier", "Don’t shout!"),
   v("😮‍💨", "sigh", "soupirer", "She sighed deeply."),
   v("🫣", "glance", "jeter un coup d’œil", "He glanced at his watch.")],
  [d("Narrator", "It was late. The house was silent.", "Il était tard. La maison était silencieuse."),
   d("Narrator", "Suddenly, someone knocked at the door.", "Soudain, quelqu’un a frappé à la porte."),
   d("Emma", "“Who’s there?” I whispered.", "« Qui est là? » ai-je chuchoté."),
   d("Narrator", "No answer. I tiptoed to the window and glanced outside.", "Pas de réponse. Je me suis approchée de la fenêtre sur la pointe des pieds et j’ai jeté un coup d’œil dehors.")],
  "En anglais, la ponctuation du dialogue utilise des guillemets « “ ” » et la virgule à l’intérieur : “Don’t move,” she whispered.",
  [ch("« Shh! » she ___. (très doucement)", ["shouted", "whispered", "rushed"], 1, "whisper = chuchoter."),
   ch("We ___ along the beach, enjoying the sunset.", ["strolled", "rushed", "shouted"], 0, "stroll = flâner."),
   ch("He ___ at his watch. He was late.", ["glanced", "sighed", "whispered"], 0, "glance = jeter un coup d’œil."),
   ch("Little ___ I know what would happen.", ["did", "had", "was"], 0, "Little did I know = j’étais loin de me douter."),
   li("He rushed into the room.", ["He rushed into the room.", "He rushed in the room.", "He brushed into the room."], 0, "rush = se précipiter."),
   od("She sighed and closed the door", "Elle a soupiré et a fermé la porte", "sigh = soupirer.")]),
])
